        deposit &&
        (!withdrawal ||
          deposit.action !== "deposit" ||
          deposit.account !== st.destinationAccount ||
          deposit.pool !== st.destinationPool ||
          deposit.planId !== st.planId ||
          deposit.slot < withdrawal.slot)
